package com.bautruc.ecommerce.commerce.application;
import java.time.Instant;import java.util.*;import com.bautruc.ecommerce.commerce.domain.CheckoutOperation;import com.bautruc.ecommerce.commerce.infrastructure.CheckoutOperationJpaRepository;import com.bautruc.ecommerce.common.exception.BusinessException;import com.bautruc.ecommerce.common.time.BusinessClock;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class CheckoutOperationService{
 private final CheckoutOperationJpaRepository operations;private final BusinessClock clock;public CheckoutOperationService(CheckoutOperationJpaRepository o,BusinessClock c){operations=o;clock=c;}
 @Transactional public CheckoutOperation acquire(Long userId,String rawKey,String requestHash){String key=validateKey(rawKey);Instant now=clock.now();operations.insertStarted(userId,key,requestHash,now);CheckoutOperation op=operations.findByUserIdAndIdempotencyKey(userId,key).orElseThrow();if(!op.getRequestHash().equals(requestHash))throw new BusinessException(CommerceErrorCodes.IDEMPOTENCY_KEY_REUSED,"Idempotency key was used with a different request.",HttpStatus.CONFLICT);return op;}
 private String validateKey(String raw){if(raw==null||raw.isBlank()||raw.length()>64)throw new BusinessException(CommerceErrorCodes.IDEMPOTENCY_KEY_REQUIRED,"A UUID v4 Idempotency-Key is required.");try{UUID id=UUID.fromString(raw.trim());if(id.version()!=4||!id.toString().equalsIgnoreCase(raw.trim()))throw new IllegalArgumentException();return id.toString();}catch(IllegalArgumentException e){throw new BusinessException(CommerceErrorCodes.IDEMPOTENCY_KEY_REQUIRED,"A UUID v4 Idempotency-Key is required.");}}
}
